<?php
require_once __DIR__.'/StoryAuthoringService.php';
require_once __DIR__.'/AiConnectionService.php';

final class InkyStarterService
{
    public static function draft(array $user,array $input): array
    {
        $genreId=(int)($input['genre_id']??0);$q=db()->prepare('SELECT label_text FROM story_genres WHERE genre_id=? AND active=1');$q->execute([$genreId]);$genre=trim((string)$q->fetchColumn());if($genre==='')throw new RuntimeException('Choose a genre for the starter.');
        $idea=self::text($input['idea']??'','story idea',2000);if(mb_strlen($idea)<20)throw new RuntimeException('Give Inky at least a sentence about the story.');$tone=self::text($input['tone']??'','tone',160,false)?:'Warm, curious, and accessible';
        $system='You are Inky, a patient story-building assistant for new interactive-fiction writers. Build a small first playable slice from the supplied idea. Use only the writer\'s idea and genre as creative input. Return JSON only with this exact shape: {"title":"short player-facing title","code":"STABLE_STORY_CODE","setting_name":"short setting","archetype":"Interactive Drama","scenario_text":"80 to 180 words of player-facing premise","location":{"location_code":"STABLE_LOCATION_CODE","label_text":"location name","description":"short location description"},"character":{"role_code":"STABLE_ROLE_CODE","name":"character name","public_description":"short public identity","private_knowledge":"optional private fact","starting_location":"exact location name","goal_text":"clear goal","fear_text":"clear fear","pronoun_set":"HE|SHE|IT"},"event":{"event_code":"OPENING_EVENT_CODE","phase":"EXPOSITION|INCITING_INCIDENT|RISING_ACTION|CLIMAX|RESOLUTION","headline":"event headline","event_text":"player-facing opening event"},"decision":{"prompt_text":"focused player-facing decision prompt"},"options":[{"option_code":"OPTION_ONE","label":"first meaningful choice","result_text":"visible narrative consequence"},{"option_code":"OPTION_TWO","label":"second meaningfully different choice","result_text":"visible narrative consequence"}],"endings":{"aftermath":"short immediate aftermath","invitation":"short replay hook"}}. Stable codes use uppercase letters, numbers, and underscores. The character starting_location must exactly match the location label. This is a starter, so create one player character and exactly two options; do not add PHP, schema, simulation rules, or engine vocabulary. Do not use markdown or additional keys.';
        $prompt=json_encode(['genre'=>$genre,'writer_idea'=>$idea,'desired_tone'=>$tone,'scope'=>'one opening decision with two options and a small ending'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($prompt===false)throw new RuntimeException('The starter request could not be prepared.');
        $response=AiConnectionService::completeJson('INKY_STORY_STARTER',$system,$prompt);return['draft'=>self::validatedDraft((array)$response['data']),'model'=>$response['model']];
    }

    public static function apply(array $user,int $genreId,array $draft): array
    {
        $draft=self::validatedDraft($draft);$draft['code']=self::availableStoryCode($draft['code']);$pdo=db();$pdo->beginTransaction();
        try{
            $plotId=StoryAuthoringService::createStory($user,['title'=>$draft['title'],'code'=>$draft['code'],'genre_id'=>$genreId,'setting_name'=>$draft['setting_name'],'archetype'=>$draft['archetype'],'max_players'=>1,'max_npcs'=>0,'scenario_text'=>$draft['scenario_text']]);
            StoryAuthoringService::saveLocation($user,$plotId,['location_code'=>$draft['location']['location_code'],'label_text'=>$draft['location']['label_text'],'description'=>$draft['location']['description'],'sort_order'=>1,'active'=>1]);
            StoryAuthoringService::saveCharacter($user,$plotId,['role_code'=>$draft['character']['role_code'],'role_type'=>'PLAYER','slot_no'=>1,'name'=>$draft['character']['name'],'public_description'=>$draft['character']['public_description'],'private_knowledge'=>$draft['character']['private_knowledge'],'starting_location'=>$draft['location']['label_text'],'goal_text'=>$draft['character']['goal_text'],'fear_text'=>$draft['character']['fear_text'],'pronoun_set'=>$draft['character']['pronoun_set'],'simulation_active'=>1,'active'=>1]);
            StoryAuthoringService::saveWorldEvent($user,$plotId,['event_second'=>0,'phase'=>$draft['event']['phase'],'event_code'=>$draft['event']['event_code'],'headline'=>$draft['event']['headline'],'event_text'=>$draft['event']['event_text'],'sort_order'=>1,'active'=>1]);
            $templateId=StoryAuthoringService::saveDecision($user,$plotId,['event_code'=>$draft['event']['event_code'],'role_code'=>$draft['character']['role_code'],'actor_type'=>'PLAYER','prompt_text'=>$draft['decision']['prompt_text'],'decision_window_seconds'=>60,'active'=>1]);
            foreach($draft['options']as$index=>$option)StoryAuthoringService::saveOption($user,$plotId,['template_id'=>$templateId,'option_code'=>$option['option_code'],'label'=>$option['label'],'npc_weight'=>0,'rationale_text'=>null,'result_text'=>$option['result_text'],'sort_order'=>$index+1,'active'=>1]);
            StoryAuthoringService::saveStorySection($user,$plotId,['section_code'=>'AFTERMATH','label_text'=>'Aftermath','description'=>'What changes immediately after the first decision.','sort_order'=>80,'active'=>1]);
            StoryAuthoringService::saveStorySection($user,$plotId,['section_code'=>'INVITATION','label_text'=>'Invitation','description'=>'A final question that invites another playthrough.','sort_order'=>90,'active'=>1]);
            StoryAuthoringService::saveResolution($user,$plotId,['section_code'=>'AFTERMATH','section_order'=>80,'priority'=>100,'fragment_text'=>$draft['endings']['aftermath'],'active'=>1]);
            StoryAuthoringService::saveResolution($user,$plotId,['section_code'=>'INVITATION','section_order'=>90,'priority'=>100,'fragment_text'=>$draft['endings']['invitation'],'active'=>1]);
            $pdo->commit();return['plot_id'=>$plotId,'title'=>$draft['title']];
        }catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
    }

    private static function validatedDraft(array $input): array
    {
        $title=self::text($input['title']??'','title',190);$code=self::code((string)($input['code']??$title));if($code==='')$code=self::code($title);if($code==='')throw new RuntimeException('Inky’s starter needs a title that can become a stable code.');$scenario=self::text($input['scenario_text']??'','scenario briefing',4000);if(mb_strlen($scenario)<80)throw new RuntimeException('Inky’s starter needs a scenario briefing of at least 80 characters.');
        $locationInput=is_array($input['location']??null)?$input['location']:[];$locationLabel=self::text($locationInput['label_text']??'','location name',190);$locationCode=self::code((string)($locationInput['location_code']??$locationLabel));if($locationCode==='')$locationCode=self::code($locationLabel);if($locationCode==='')throw new RuntimeException('Inky’s starter needs a location name that can become a stable code.');
        $characterInput=is_array($input['character']??null)?$input['character']:[];$characterName=self::text($characterInput['name']??'','character name',190);$roleCode=self::code((string)($characterInput['role_code']??$characterName));if($roleCode==='')$roleCode=self::code($characterName);if($roleCode==='')throw new RuntimeException('Inky’s starter needs a character name that can become a stable code.');$pronoun=strtoupper(self::text($characterInput['pronoun_set']??'IT','pronoun set',3,false)?:'IT');if(!in_array($pronoun,['HE','SHE','IT'],true))$pronoun='IT';
        $eventInput=is_array($input['event']??null)?$input['event']:[];$eventCode=self::code((string)($eventInput['event_code']??'OPENING_EVENT'));if($eventCode==='')$eventCode='OPENING_EVENT';$phase=strtoupper(self::text($eventInput['phase']??'EXPOSITION','event phase',30,false)?:'EXPOSITION');if(!in_array($phase,['EXPOSITION','INCITING_INCIDENT','RISING_ACTION','CLIMAX','RESOLUTION'],true))$phase='EXPOSITION';
        $decisionInput=is_array($input['decision']??null)?$input['decision']:[];$optionsInput=is_array($input['options']??null)?$input['options']:[];$options=[];foreach(array_slice($optionsInput,0,2)as$row){if(!is_array($row))continue;$label=self::text($row['label']??'','choice label',500);$optionCode=self::code((string)($row['option_code']??$label));if($optionCode==='')$optionCode='OPTION_'.(count($options)+1);$options[]=['option_code'=>$optionCode,'label'=>$label,'result_text'=>self::text($row['result_text']??'','choice consequence',2000)];}if(count($options)!==2||$options[0]['option_code']===$options[1]['option_code'])throw new RuntimeException('Inky’s starter must include two distinct usable choices.');
        $endings=is_array($input['endings']??null)?$input['endings']:[];return['title'=>$title,'code'=>$code,'setting_name'=>self::text($input['setting_name']??'Unspecified setting','setting',190,false)?:'Unspecified setting','archetype'=>self::text($input['archetype']??'Interactive Drama','archetype',120,false)?:'Interactive Drama','scenario_text'=>$scenario,'location'=>['location_code'=>$locationCode,'label_text'=>$locationLabel,'description'=>self::text($locationInput['description']??'','location description',1200,false)],'character'=>['role_code'=>$roleCode,'name'=>$characterName,'public_description'=>self::text($characterInput['public_description']??'','public character description',1500),'private_knowledge'=>self::text($characterInput['private_knowledge']??'','private knowledge',1500,false),'starting_location'=>$locationLabel,'goal_text'=>self::text($characterInput['goal_text']??'','character goal',800),'fear_text'=>self::text($characterInput['fear_text']??'','character fear',800,false),'pronoun_set'=>$pronoun],'event'=>['event_code'=>$eventCode,'phase'=>$phase,'headline'=>self::text($eventInput['headline']??'','event headline',255),'event_text'=>self::text($eventInput['event_text']??'','event text',2500)],'decision'=>['prompt_text'=>self::text($decisionInput['prompt_text']??'','decision prompt',1500)],'options'=>$options,'endings'=>['aftermath'=>self::text($endings['aftermath']??'','aftermath ending',2500),'invitation'=>self::text($endings['invitation']??'','invitation ending',2500)]];
    }

    private static function availableStoryCode(string $code): string{$base=$code;$candidate=$base;$suffix=2;while(true){$q=db()->prepare('SELECT 1 FROM plots WHERE code=? LIMIT 1');$q->execute([$candidate]);if(!$q->fetchColumn())return$candidate;$candidate=$base.'_'.$suffix++;if($suffix>1000)throw new RuntimeException('Inky could not find an unused story code.');}}
    private static function code(string$value): string{$value=strtoupper(trim((string)preg_replace('/[^A-Za-z0-9]+/','_',trim($value)),'_'));return mb_substr($value,0,100);}
    private static function text(mixed$value,string$label,int$max,bool$required=true): string{$value=is_scalar($value)?trim((string)$value):'';if($required&&$value==='')throw new RuntimeException('Inky’s starter is missing a usable '.$label.'.');if(mb_strlen($value)>$max)throw new RuntimeException('Inky’s '.$label.' is too long.');return$value;}
}
